head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > oninsertrow]<br/>DataList 모듈에서 Row 가 '삽입' 되면 발생합니다.",
    "validation" : [
        "setRow 계열의 메소드로 Row 데이터를 '삽입' 할 수 있습니다.",
        "Row 가 '삭제', '제거' 되거나 전체 데이터가 로드된 경우엔 oninsertrow 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩    
    target1.bind("oninsertrow", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oninsertrow=====");
    });      

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



scwin.btn_insertJSON_onclick = function (e) {
	target1.insertJSON(0, [
        {col1:"insert1",col2:"insert2",col3:"insert3",col4:"insert4"},
        {col1:"insert5",col2:"insert6",col3:"insert7",col4:"insert8"}
    ]);
};



scwin.btn_setData_onclick = function (e) {     
    target1.setData(["setcol1","setcol2","setcol3","setcol4", "setcol5","setcol6","setcol7","setcol8"]);
};



scwin.btn_setRowJSON_onclick = function (e) {
    target1.setRowJSON(0, {col1:"setcol1",col2:"setcol2",col3:"setcol3",col4:"setcol4"});
};



scwin.btn_removeRow_onclick = function (e) {  
    target1.removeRow();
}



scwin.btn_deleteRow_onclick = function (e) {  
    target1.deleteRow(0);
}
